type Result = { total: number; reasoning: number; subject: number; flexibility: number; clarity: number; strengths: string[]; nextSteps: string[]; error: string }
type SessionLog = { id: string; title: string; score: number; date: string; events: string[] }
type Activity = { title: string; type: string; learned: string; question: string }
type SectionScore = { attempted: number; correct: number }
type ProgressState = { sessions: number; interviewScores: number[]; testCorrect: number; testAttempted: number; streak: number; completed: string[]; mistakes: Record<string, number>; logs: SessionLog[]; activities: Activity[]; weeklyDone: number[]; wrongQuestionIds: string[]; bookmarkedQuestionIds: string[]; sectionScores: Record<string, SectionScore> }
const emptyProgress: ProgressState = { sessions: 0, interviewScores: [], testCorrect: 0, testAttempted: 0, streak: 0, completed: [], mistakes: {}, logs: [], activities: [], weeklyDone: [], wrongQuestionIds: [], bookmarkedQuestionIds: [], sectionScores: {} }

function scoreAnswer(answer: string, concepts: string[]): Result {
  const clean = answer.trim().toLowerCase(), words = clean ? clean.split(/\s+/).length : 0
  const reasoningHits = ["because", "therefore", "so", "if", "then", "implies", "since", "hence"].filter(word => clean.includes(word)).length
  const flexibleHits = ["however", "although", "alternative", "depends", "unless", "counter", "assumption", "could"].filter(word => clean.includes(word)).length
  const conceptHits = concepts.filter(word => clean.includes(word.toLowerCase())).length
  const reasoning = Math.min(25, 8 + reasoningHits * 4 + (words > 55 ? 5 : 0))
  const subject = Math.min(25, 5 + Math.round((conceptHits / Math.max(concepts.length, 1)) * 20))
  const flexibility = Math.min(25, 6 + flexibleHits * 4 + (clean.includes("example") ? 3 : 0))
  const clarity = Math.min(25, words >= 55 && words <= 260 ? 22 : words >= 30 ? 17 : words >= 12 ? 11 : 5)
  const total = reasoning + subject + flexibility + clarity, strengths: string[] = [], nextSteps: string[] = []
  if (reasoning >= 18) strengths.push("Your reasoning was visible rather than hidden behind a conclusion."); else nextSteps.push("Link each step explicitly with ‘because’, ‘if’ and ‘therefore’.")
  if (subject >= 17) strengths.push("You selected relevant subject ideas and used them purposefully."); else nextSteps.push(`Bring in the core ideas: ${concepts.slice(0, 3).join(", ")}.`)
  if (flexibility >= 17) strengths.push("You tested an assumption or considered an alternative."); else nextSteps.push("State one assumption and test a counterexample or edge case.")
  if (clarity >= 18) strengths.push("The explanation was developed without losing focus."); else nextSteps.push(words < 30 ? "Develop a method, example and provisional conclusion." : "Use claim → reason → test → conclusion.")
  const error = words < 20 ? "Under-developed reasoning" : conceptHits === 0 ? "Knowledge connection" : reasoningHits < 2 ? "Logical chain" : flexibleHits === 0 ? "Unexamined assumption" : "No dominant error"
  return { total, reasoning, subject, flexibility, clarity, strengths, nextSteps, error }
}

function useTimer(minutes: number) {
  const [seconds, setSeconds] = useState(minutes * 60), [running, setRunning] = useState(false)
  useEffect(() => { if (!running || seconds <= 0) return; const id = window.setInterval(() => setSeconds(value => value - 1), 1000); return () => window.clearInterval(id) }, [running, seconds])
  const reset = useCallback(() => { setSeconds(minutes * 60); setRunning(false) }, [minutes])
  return { seconds, running, setRunning, reset }
}
const formatTime = (seconds: number) => `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, "0")}`
const daysUntil = (date: string) => Math.max(0, Math.ceil((new Date(`${date}T18:00:00`).getTime() - Date.now()) / 86400000))

