  const [test, setTest] = useState<TestName>(defaultTest), [mode, setMode] = useState<"Diagnostic" | "Adaptive" | "Question bank" | "Redo mistakes" | "Bookmarks" | "Full mock">("Diagnostic"), [section, setSection] = useState("All sections"), [difficultyFilter, setDifficultyFilter] = useState("All"), [index, setIndex] = useState(0), [selected, setSelected] = useState<number | null>(null), [checked, setChecked] = useState(false), [flagged, setFlagged] = useState<number[]>([]), [mockSeed, setMockSeed] = useState(1), [mockAnswers, setMockAnswers] = useState<Record<number, number>>({}), [mockDone, setMockDone] = useState(false), [writingPhase, setWritingPhase] = useState(false), [writingChoice, setWritingChoice] = useState(0), [writingAnswer, setWritingAnswer] = useState("")
  const blueprint = testBlueprints[test]
